      coinName: map['coin_name'] as String,
      datetime: DateTime.fromMillisecondsSinceEpoch(map['datetime'] as int),
      profitLoss: map['profit_loss'] as double,
    );
  }
}

List<Transaction> sortTransactionsByAverageProfit(List<Transaction> transactions) {
  List<double> profits = [];
  for (var transaction in transactions) {
    profits.add((transaction.profitLoss > 0 ? transaction.profitLoss : -transaction.profitLoss).abs());
  }
  List<int> indices = List.generate(transactions.length, (i) => i);
