    double avgA = (profits[a] + profits[indices[a + 1] ?? transactions.last.profitLoss]) / 2;
    double avgB = (profits[b] + profits[indices[b + 1] ?? transactions.last.profitLoss]) / 2;
    return avgB.compareTo(avgA);
  });
