    : QWidget(parent),
      m_matrixWidth(256),
      m_matrixHeight(256),
      m_zoomLevel(1),
      m_bitmapWidth(m_matrixWidth * m_zoomLevel),
      m_bitmapHeight(m_matrixHeight * m_zoomLevel),
      m_bitmap(m_bitmapWidth, m_bitmapHeight, QBitmap::Format_ARGB32),
      m_zoomMatrix(QMatrix())
{
    // Initialize the bitmap with all-white pixels
    QImage image(&m_bitmap, m_bitmapWidth, m_bitmapHeight, QImage::Format_ARGB32);
    image.fill(Qt::white);
}

void MatrixCanvas::paintEvent(QPaintEvent *)
{
    QPainter painter(this);
    painter.setBrush(Qt::NoBrush);
    painter.drawBitmap(QPoint(), m_bitmap, m_zoomMatrix);
}

