```swift
let homophoneDictionary: [String: String] = [
    "there": "their",
    "they're": "they are",
    "too": ["to", "two"] // We'll handle both cases here
]

func replaceHomophones(in sentence: String) -> String {
    var result = ""

    for (key, values) in homophoneDictionary {
        // Replace exact matches first
        result = result.replacingOccurrences(of: key, with: values[values.count - 1]) // Use last value from array for 'too'

        // Then, recursively replace partial matches
        result = result.replacingOccurrences(of: "$key", with: String(describing: values), options: .regularExpression)
    }

    return result
}

