function getValuesFromObjectPath(object, path) {
  let currentObject = object;
  const keys = path.split('.');
  const values = [];

  for (let I = 0; I < keys.length; i++) {
    if (!currentObject[keys[i]]) {
      // Key not found, exit early
      return values;
    }

    if (i === keys.length - 1 && typeof currentObject[keys[i]] !== 'object') {
      // Last key is reached, add value
      values.push(currentObject[keys[i]]);
    } else if (typeof currentObject[keys[i]] === 'object') {
      // Recursively call the function with the next level of objects
      const subValues = getValuesFromObjectPath(currentObject[keys[i]], keys.slice(i+1).join('.'));
      values.push(...subValues);
    }

    currentObject = currentObject[keys[i]];
  }

  return values;
}

// Usage example:
